import os
import sys

print("CWD:", os.getcwd())
print("Python:", sys.version)
for entry in sorted(os.listdir(".")):
    full = os.path.join(".", entry)
    if os.path.isfile(full):
        print(f"FILE {entry} ({os.path.getsize(full)} bytes)")
    elif os.path.isdir(full):
        print(f"DIR  {entry}/")

# Check library availability
for lib in ("pypdf", "reportlab", "pdfplumber"):
    try:
        __import__(lib)
        print(f"LIB {lib}: available")
    except Exception as exc:
        print(f"LIB {lib}: NOT available ({exc})")
